#!/usr/bin/env node
/**
 * Pulls the product catalog from Postgres (the admin app's database) and
 * writes it to src/lib/products-data.generated.ts as a plain array literal.
 *
 * Runs before dev/build (see package.json `predev`/`prebuild`). If
 * SHOP_DATABASE_URL isn't set, this is a no-op — the last-generated file
 * (checked into git as a fallback snapshot) is used as-is, so a fresh clone
 * without DB access still builds.
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { config } from "dotenv";
import postgres from "postgres";

const __dirname = dirname(fileURLToPath(import.meta.url));
config({ path: join(__dirname, "..", ".env") });

const connectionString = process.env.SHOP_DATABASE_URL;
const outFile = join(
  __dirname,
  "..",
  "src",
  "lib",
  "products-data.generated.ts",
);

if (!connectionString) {
  console.log(
    "sync-products: SHOP_DATABASE_URL not set, skipping — using the committed snapshot as-is.",
  );
  process.exit(0);
}

const SCRIPT = "sync-products";
/**
 * The guard above catches a missing variable. It does not catch a variable that
 * is set and unreachable, which is the ordinary case on a dev machine: the URL
 * is committed in .env and points at 127.0.0.1:55432, an SSH tunnel to the shop
 * database that is only up when somebody opened it.
 *
 * Without this the script hard-fails on ECONNREFUSED and takes `npm run dev`
 * with it, so the site cannot be run at all -- including to change a line of
 * static copy that has nothing to do with the database. Unreachable is treated
 * the same as unconfigured: fall back to the committed snapshot and say so.
 */
async function reachable(sql) {
  try {
    await sql`SELECT 1`;
    return true;
  } catch (error) {
    console.log(
      `${SCRIPT}: cannot reach the shop database (${error.code || error.message}) — ` +
        "using the committed snapshot as-is. Open the SSH tunnel to refresh it.",
    );
    return false;
  }
}

const sql = postgres(connectionString);
if (!(await reachable(sql))) {
  await sql.end({ timeout: 1 });
  process.exit(0);
}

const products = await sql`
  SELECT id, slug, name, category, art, price_cents, is_new, blurb, description
  FROM products
  ORDER BY created_at
`;

const colours = await sql`
  SELECT id, product_id, name, swatch, body, ink, images
  FROM product_colours
  ORDER BY sort_order
`;

const stock = await sql`
  SELECT colour_id, size, quantity
  FROM colour_stock
`;

const SIZE_ORDER = ["S", "M", "L", "XL", "XXL"];

const catalog = products.map((p) => {
  const productColours = colours.filter((c) => c.product_id === p.id);
  const sizeSet = new Set();
  for (const c of productColours) {
    for (const row of stock.filter((s) => s.colour_id === c.id)) {
      sizeSet.add(row.size);
    }
  }

  return {
    slug: p.slug,
    name: p.name,
    price: p.price_cents / 100,
    category: p.category,
    art: p.art,
    ...(p.is_new ? { isNew: true } : {}),
    colours: productColours.map((c) => ({
      name: c.name,
      swatch: c.swatch,
      body: c.body,
      ink: c.ink,
      ...(c.images.length > 0 ? { images: c.images } : {}),
    })),
    sizes: SIZE_ORDER.filter((s) => sizeSet.has(s)),
    blurb: p.blurb,
    description: p.description,
  };
});

await sql.end();

const banner = `/**
 * AUTO-GENERATED by scripts/sync-products.mjs — do not edit by hand.
 * Run \`npm run sync:products\` to refresh from the admin database.
 * Checked into git as a fallback snapshot for builds without DB access.
 */
import type { Product } from "./products";

export const products: Product[] = `;

writeFileSync(outFile, banner + JSON.stringify(catalog, null, 2) + ";\n");
console.log(`sync-products: wrote ${catalog.length} products to ${outFile}`);
